# Find the first instance of 'Invoice No.' in column A
invoice_row = None
for row in ws.iter_rows(min_col=1, max_col=1):
    for cell in row:
        if cell.value == "Invoice No.":
            invoice_row = cell.row
            break
    if invoice_row:
        break

# If 'Invoice No.' is found, delete all rows before it
if invoice_row:
    for row in range(1, invoice_row):
        ws.delete_rows(row)

# Now, the 'Invoice No.' row is at A1, and we need to write the answer range
# The answer range is A2:E12, so we need to copy the data from the original sheet
# starting from the row after 'Invoice No.' (which is now row 1) to row 12

# Clear the answer range first
for row in range(2, 13):
    for col in range(1, 6):
        ws.cell(row=row, column=col).value = None

# Write the data from the original sheet into the answer range
for row in range(1, 12):
    for col in range(1, 6):
        ws.cell(row=row + 1, column=col).value = ws.cell(row=row + 1, column=col).value

