from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

def number_to_letters(n):
    """Convert a number to base-26 letters (like Excel column labels)."""
    letters = ''
    while n > 0:
        n, rem = divmod(n - 1, 26)
        letters = chr(65 + rem) + letters
    return letters

def generate_urns(sheet):
    urns = []
    last_number = None
    current_letter = 0

    for row in sheet.iter_rows(min_col=1, max_col=1, values_only=True):
        value = row[0]
        if value is not None:
            try:
                # If the value is a number, convert to integer
                number = int(value)
                last_number = number
                current_letter = 0
                urns.append(str(number))
            except ValueError:
                # If the value is a string like '5a', extract the number part
                if value[0].isdigit():
                    number_part = ''
                    for ch in value:
                        if ch.isdigit():
                            number_part += ch
                        else:
                            break
                    if number_part:
                        last_number = int(number_part)
                        current_letter = 0
                        urns.append(value)
                else:
                    urns.append('')
        else:
            if last_number is not None:
                current_letter += 1
                if current_letter <= 26:
                    urn = f"{last_number}{chr(97 + current_letter - 1)}"
                else:
                    # Convert current_letter to base-26 letters
                    urn = f"{last_number}{number_to_letters(current_letter)}"
                urns.append(urn)
            else:
                urns.append('')

    return urns

def main():
    # Load the workbook and select the sheet
    wb = load_workbook('input.xlsx')
    sheet = wb['Sheet1']

    # Generate the URNs
    urns = generate_urns(sheet)

    # Write the URNs back to column A
    for row in range(1, len(urns) + 1):
        sheet[f'A{row}'] = urns[row - 1]

    # Save the workbook
    wb.save('output.xlsx')

if __name__ == '__main__':
    main()
