from openpyxl import load_workbook
from datetime import datetime, timedelta
import calendar

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb.active

# Find the header row and first data row
header_row = None
data_start_row = None

for row in ws.iter_rows(min_row=1, max_row=10):
    for cell in row:
        if cell.value == "Year":
            header_row = cell.row
            break
    if header_row:
        break

# Find the year column (2018)
year_col = None
for col in ws.iter_cols(min_col=1, max_col=15):
    for cell in col:
        if cell.value == 2018:
            year_col = cell.column
            break
    if year_col:
        break

# Find the row with "Night shift" to get the night shift data
night_shift_row = None
for row in ws.iter_rows(min_row=1, max_row=10):
    for cell in row:
        if cell.value == "Night shift":
            night_shift_row = cell.row
            break
    if night_shift_row:
        break

# Find the month headers (Jan to Dec)
month_headers = []
for col in ws.iter_cols(min_col=2, max_col=13):
    for cell in col:
        if cell.value in ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]:
            month_headers.append(cell.column)
            break

# Get the year value from the column
year_value = ws.cell(row=header_row, column=year_col).value

# Calculate the number of days in the given year
is_leap = calendar.isleap(year_value)
days_in_year = 366 if is_leap else 365

# Calculate the number of night shifts for the given year
night_shifts = 0
for col in month_headers:
    night_shifts += ws.cell(row=night_shift_row, column=col).value

# Calculate the percentage of night shifts
percentage_night_shifts = night_shifts / days_in_year

# Format the percentage according to the rules
if percentage_night_shifts == 0:
    formatted_percentage = f"{int(percentage_night_shifts)}"
elif abs(percentage_night_shifts - round(percentage_night_shifts, 1)) < 1e-9:
    formatted_percentage = f"{round(percentage_night_shifts, 1)}"
else:
    formatted_percentage = f"{percentage_night_shifts:.9f}"

# Write the formatted percentage to the answer range (B11:M11)
for col in range(2, 13):
    ws.cell(row=11, column=col, value=formatted_percentage)

# Save the workbook
wb.save("output.xlsx")
